#include <bits/stdc++.h>
using namespace std;

int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int n;
        scanf("%d",&n);
        vector<int> p(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&p[i]);

        vector<pair<int,int>> edges(n-1);
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<n-1;i++){
            int u,v; scanf("%d%d",&u,&v);
            edges[i]={u,v};
            adj[u].push_back({v,i});
            adj[v].push_back({u,i});
        }

        // Precompute parent and depth via BFS from root=1
        vector<int> par(n+1,0), depth(n+1,0);
        vector<int> bfs_order;
        {
            vector<bool> vis(n+1,false);
            queue<int> q; q.push(1); vis[1]=true;
            while(!q.empty()){
                int u=q.front(); q.pop(); bfs_order.push_back(u);
                for(auto [v,ei]:adj[u]) if(!vis[v]){vis[v]=true;par[v]=u;depth[v]=depth[u]+1;q.push(v);}
            }
        }

        // Function: find next node on path from 'from' to 'to' in tree
        // Using LCA-based approach: precompute ancestors
        // For direction: given edge (u,v), does token at u want to go toward v?
        // Token at node u is p[u], target is p[u]. We need to check if v is on path from u to p[u].

        auto on_path_toward = [&](int node, int neighbor, int target) -> bool {
            // Is 'neighbor' on the path from 'node' to 'target'?
            // neighbor is adjacent to node. 
            // If neighbor is parent of node: target is not in subtree of node
            // If neighbor is child of node: target is in subtree of neighbor
            // We check using LCA / ancestor queries
            // Simple: compute path by going up from target and node
            // Use depth + parent climbing

            // Check if target is in subtree of neighbor (when neighbor is child of node)
            // or target is outside subtree of node (when neighbor is parent of node)
            if(par[neighbor]==node){
                // neighbor is child of node. Check if target is in subtree of neighbor.
                // Walk up from target; if we reach neighbor before node, yes.
                int x=target;
                while(depth[x]>depth[neighbor]) x=par[x];
                return x==neighbor;
            } else {
                // neighbor is parent of node. Target is toward neighbor if target is NOT in subtree of node.
                int x=target;
                while(depth[x]>depth[node]) x=par[x];
                return x!=node;
            }
        };

        vector<vector<int>> results;
        for(int iter=0;iter<2*n&&iter<6000;iter++){
            bool done=true;
            for(int i=1;i<=n;i++) if(p[i]!=i){done=false;break;}
            if(done) break;

            // Score edges: prefer edges where both endpoints want to swap across
            vector<pair<int,int>> scored;
            for(int i=0;i<n-1;i++){
                auto [u,v]=edges[i];
                if(p[u]==u&&p[v]==v) continue;
                bool u_wants = (p[u]!=u) && on_path_toward(u,v,p[u]);
                bool v_wants = (p[v]!=v) && on_path_toward(v,u,p[v]);
                int pri = (u_wants?1:0)+(v_wants?1:0);
                if(pri>0) scored.push_back({pri,i});
            }
            sort(scored.begin(),scored.end(),[](auto&a,auto&b){return a.first>b.first;});

            vector<bool> used(n+1,false);
            vector<int> matching;
            for(auto [pri,ei]:scored){
                auto [u,v]=edges[ei];
                if(!used[u]&&!used[v]){used[u]=used[v]=true;matching.push_back(ei);swap(p[u],p[v]);}
            }
            if(matching.empty()) break;
            results.push_back(matching);
        }
        printf("%d\n",(int)results.size());
        for(auto&m:results){printf("%d",(int)m.size());for(int ei:m) printf(" %d",ei+1);printf("\n");}
    }
}
